<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import type { ConfigRevisionSummary, ConfigTemplateCreateInput, ConfigTemplateSummary } from '@cyberboard/types'
import StatusBadge from '@cyberboard/ui/components/StatusBadge.vue'; import StatePanel from '@cyberboard/ui/components/StatePanel.vue'; import { adminApi, getApiErrorMessage, normalizePage } from '../api'
const tab=ref<'templates'|'revisions'>('templates'); const loading=ref(true); const error=ref(''); const saving=ref(false); const formError=ref(''); const showForm=ref(false); const editingId=ref<string|null>(null); const templates=ref<ConfigTemplateSummary[]>([]); const revisions=ref<ConfigRevisionSummary[]>([]); const templateTotal=ref(0); const revisionTotal=ref(0); const templatePage=ref(1); const revisionPage=ref(1); const pageSize=20
const form=reactive<ConfigTemplateCreateInput>({name:'',description:'',coreType:'sing-box',coreVersionRange:'>=1.11.0',status:'draft'})
const revisionFilters=reactive({search:'',status:''}); const currentItems=computed(()=>tab.value==='templates'?templates.value:revisions.value)
function resetForm(){Object.assign(form,{name:'',description:'',coreType:'sing-box',coreVersionRange:'>=1.11.0',status:'draft'});editingId.value=null;showForm.value=false;formError.value=''}
function editTemplate(item:ConfigTemplateSummary){Object.assign(form,{name:item.name,description:item.description,coreType:item.coreType,coreVersionRange:item.coreVersionRange,status:item.status});editingId.value=item.id;showForm.value=true}
async function loadTemplates(){const result=normalizePage(await adminApi.listConfigTemplates({page:templatePage.value,pageSize}),templatePage.value,pageSize);templates.value=result.items;templateTotal.value=result.total}
async function loadRevisions(){const result=normalizePage(await adminApi.listConfigRevisions({page:revisionPage.value,pageSize,search:revisionFilters.search,status:revisionFilters.status||undefined}),revisionPage.value,pageSize);revisions.value=result.items;revisionTotal.value=result.total}
async function load(){loading.value=true;error.value='';try{await Promise.all([loadTemplates(),loadRevisions()])}catch(cause){error.value=getApiErrorMessage(cause)}finally{loading.value=false}}
async function saveTemplate(){saving.value=true;formError.value='';try{if(editingId.value)await adminApi.updateConfigTemplate(editingId.value,form);else await adminApi.createConfigTemplate(form);resetForm();await loadTemplates()}catch(cause){formError.value=getApiErrorMessage(cause)}finally{saving.value=false}}
async function publish(item:ConfigRevisionSummary){try{await adminApi.publishConfigRevision(item.id,{expectedGeneration:item.generation});await loadRevisions()}catch(cause){error.value=getApiErrorMessage(cause)}}
async function rollback(item:ConfigRevisionSummary){try{await adminApi.rollbackConfigRevision(item.id,{targetGeneration:item.generation,reason:'管理员从控制面回滚'});await loadRevisions()}catch(cause){error.value=getApiErrorMessage(cause)}}
onMounted(load)
</script>
<template><div class="page-heading"><div><p class="eyebrow">内核配置</p><h1>配置发布</h1><p>管理模板、版本、签名校验和节点发布状态。</p></div><div><button class="button button--secondary" type="button" :disabled="loading" @click="load">刷新</button><button v-if="tab==='templates'" class="primary-button" type="button" @click="showForm=true;editingId=null">+ 新建模板</button></div></div><StatePanel v-if="error" title="配置数据操作失败" :description="error" action-label="重试" @action="load"/><section v-if="showForm&&tab==='templates'" class="panel form-panel"><div class="panel-heading"><div><h2>{{editingId?'编辑配置模板':'新建配置模板'}}</h2><p>核心版本范围会在发布前再次校验。</p></div><button class="button button--secondary" type="button" @click="resetForm">取消</button></div><form class="resource-form" @submit.prevent="saveTemplate"><label>名称<input v-model="form.name" required :disabled="saving"/></label><label>核心类型<input v-model="form.coreType" required :disabled="saving"/></label><label>版本范围<input v-model="form.coreVersionRange" required :disabled="saving"/></label><label>状态<select v-model="form.status" :disabled="saving"><option value="draft">草稿</option><option value="active">生效</option><option value="archived">归档</option></select></label><label class="form-span">描述<textarea v-model="form.description" rows="3" :disabled="saving"/></label><p v-if="formError" class="form-error" role="alert">{{formError}}</p><button class="primary-button" type="submit" :disabled="saving">{{saving?'保存中…':'保存模板'}}</button></form></section><section class="panel"><div class="tabs"><button :class="['tab',tab==='templates'&&'tab--active']" type="button" @click="tab='templates'">配置模板</button><button :class="['tab',tab==='revisions'&&'tab--active']" type="button" @click="tab='revisions'">配置版本与发布</button></div><StatePanel v-if="loading" title="正在加载配置数据" description="正在读取模板、版本和节点发布状态。"/><template v-else-if="tab==='templates'"><StatePanel v-if="!currentItems.length" title="暂无配置模板" description="控制面尚未返回配置模板。"/><div v-else class="table-wrap"><table><thead><tr><th>模板</th><th>核心</th><th>版本范围</th><th>状态</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in templates" :key="item.id"><td><strong>{{item.name}}</strong><small>{{item.description}}</small></td><td>{{item.coreType}}</td><td class="mono">{{item.coreVersionRange}}</td><td><StatusBadge :status="item.status"/></td><td>{{item.updatedAt}}</td><td><button class="row-action" type="button" @click="editTemplate(item)">编辑</button></td></tr></tbody></table><div class="pagination"><button class="button button--secondary" :disabled="templatePage<=1" @click="templatePage--;loadTemplates()">上一页</button><span>第 {{templatePage}} 页 · 共 {{templateTotal}} 条</span><button class="button button--secondary" :disabled="templatePage*pageSize>=templateTotal" @click="templatePage++;loadTemplates()">下一页</button></div></div></template><template v-else><div class="toolbar"><input v-model="revisionFilters.search" class="search-input" placeholder="搜索节点、hash 或版本" @keyup.enter="revisionPage=1;loadRevisions()"/><select v-model="revisionFilters.status" aria-label="发布状态" @change="revisionPage=1;loadRevisions()"><option value="">全部发布状态</option><option value="published">已发布</option><option value="failed">失败</option><option value="rolled_back">已回滚</option><option value="publishing">发布中</option></select></div><StatePanel v-if="!revisions.length" title="暂无配置版本" description="控制面尚未返回配置版本或发布记录。"/><div v-else class="table-wrap"><table><thead><tr><th>版本</th><th>目标节点</th><th>generation</th><th>核心</th><th>hash / 签名</th><th>校验</th><th>发布结果</th><th>操作</th></tr></thead><tbody><tr v-for="item in revisions" :key="item.id"><td class="mono">{{item.id}}<small>{{item.createdAt}}</small></td><td>{{item.nodeName}}<small class="mono">{{item.nodeId}}</small></td><td class="mono">{{item.generation}}</td><td>{{item.coreVersion}}</td><td class="mono">{{item.contentHash}}<small>签名：{{item.signatureStatus}}</small></td><td><StatusBadge :status="item.validationStatus"/></td><td><StatusBadge :status="item.publishStatus"/><small v-if="item.failureReason" class="form-error">{{item.failureReason}}</small></td><td><button class="row-action" type="button" :disabled="item.publishStatus==='publishing'" @click="publish(item)">发布</button><button class="row-action" type="button" :disabled="item.publishStatus!=='published'" @click="rollback(item)">回滚</button></td></tr></tbody></table><div class="pagination"><button class="button button--secondary" :disabled="revisionPage<=1" @click="revisionPage--;loadRevisions()">上一页</button><span>第 {{revisionPage}} 页 · 共 {{revisionTotal}} 条</span><button class="button button--secondary" :disabled="revisionPage*pageSize>=revisionTotal" @click="revisionPage++;loadRevisions()">下一页</button></div></div></template></section></template>
